bounds = [(-0.03, 0.03)] * (N * 3)

def loss(p):
    offsets = p.reshape((N, 3))
    magsens_shifted = magsens_positions_xyz + offsets
    solved = []
    for i in range(3):
        #solved.append(calc_curr_segments(ltr_data[i], mag_data[i], magsens_shifted))
        solved.append(calc_curr_segments_xyz(ltr_data[i], mag_data[i], magsens_shifted[:n], magsens_shifted[n:2*n], magsens_shifted[2*n:]))
    solved = np.array(solved).flatten()
    return np.abs(solved - target).sum()

def loss_parallel(p):
    offsets = p.reshape((N, 3))
    magsens_shifted = magsens_positions_xyz + offsets

    solved = Parallel(n_jobs=18)(
        delayed(calc_curr_segments_xyz)(
            ltr_data[i], mag_data[i], magsens_shifted[:n], magsens_shifted[n:2*n], magsens_shifted[2*n:]
        )
        for i in range(18)
    )

    solved = np.array(solved).flatten()
    return np.abs(solved - target).sum()


# Globale Variablen für Fortschrittsanzeige
pbar_global = None
pbar_local = None
best_loss_global = float('inf')
best_loss_local = float('inf')


# Nicht-parallele Loss-Funktion für differential_evolution
def loss_sequential(p):
    offsets = p.reshape((N, 3))
    magsens_shifted = magsens_positions_xyz + offsets

    solved = []
    for i in range(len(ltr_data)):
        curr = calc_curr_segments_xyz(
            ltr_data[i], mag_data[i],
            magsens_shifted[:n],
            magsens_shifted[n:2 * n],
            magsens_shifted[2 * n:]
        )
        solved.append(curr)

    solved = np.array(solved).flatten()
    return np.abs(solved - target).sum()


# Callback für differential_evolution
def callback_global(xk, convergence):
    global best_loss_global, pbar_global
    val = loss_sequential(xk)
    best_loss_global = min(best_loss_global, val)
    pbar_global.update(1)
    pbar_global.set_postfix({"loss": f"{val}", "best": f"{best_loss_global}"})
    return False  # False = weitermachen, True = abbrechen


# Callback für L-BFGS-B
def callback_local(xk):
    global best_loss_local, pbar_local
    val = loss_sequential(xk)
    best_loss_local = min(best_loss_local, val)
    pbar_local.update(1)
    pbar_local.set_postfix({"loss": f"{val}", "best": f"{best_loss_local}"})

